// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    // the test contract is C's bank (deployer); it must be able to receive the 1-wei fee
    receive() external payable {}

    function testFuzz_property(uint256 t, uint256 d, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.warp(t);
        vm.roll(d);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        uint256 p = c.pot();
        // General rule: after a correctly-priced play, the pot is either the untouched
        // 10-wei pot (no win) or fully emptied (win paid out to bank + winner).
        assertTrue(p == 10 || p == 0, "pot must be 10 (no win) or 0 (win)");
    }
}
